import{_ as a,o as r,c as t,aB as o}from"./chunks/framework.CgPQczGq.js";const u=JSON.parse('{"title":"References","description":"","frontmatter":{},"headers":[],"relativePath":"pages/vSmartMOM/References.md","filePath":"pages/vSmartMOM/References.md","lastUpdated":null}'),i={name:"pages/vSmartMOM/References.md"};function n(s,e,l,d,c,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="References" tabindex="-1">References <a class="header-anchor" href="#References" aria-label="Permalink to &quot;References {#References}&quot;">​</a></h1><p>For BibTeX entries, use <a href="https://github.com/RemoteSensingTools/vSmartMOM.jl/blob/main/CITATION.bib" target="_blank" rel="noreferrer"><code>CITATION.bib</code></a> at the repository root.</p><h2 id="How-To-Cite" tabindex="-1">How To Cite <a class="header-anchor" href="#How-To-Cite" aria-label="Permalink to &quot;How To Cite {#How-To-Cite}&quot;">​</a></h2><p>If you use vSmartMOM.jl, please cite the vSmartMOM model paper and the JOSS software paper:</p><ul><li><p>Sanghavi, S., Davis, A. B., and Eldering, A. (2014). vSmartMOM: A vector matrix operator method-based radiative transfer model linearized with respect to aerosol properties. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 133, 412-433. <a href="https://doi.org/10.1016/j.jqsrt.2013.09.004" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2013.09.004</a></p></li><li><p>Jeyaram, R., Sanghavi, S., and Frankenberg, C. (2022). vSmartMOM.jl: An open-source Julia package for atmospheric radiative transfer and remote sensing tools. <em>Journal of Open Source Software</em>, 7(80), 4575. <a href="https://doi.org/10.21105/joss.04575" target="_blank" rel="noreferrer">https://doi.org/10.21105/joss.04575</a></p></li></ul><p>For rotational Raman scattering (RRS), please also cite the three papers under Raman Scattering below; for exoplanets and brown dwarfs, the three papers under Exoplanets and Brown Dwarfs. Use the other method references below when your work depends on a specific solver component.</p><h2 id="Matrix-Operator-RT-and-Jacobians" tabindex="-1">Matrix-Operator RT and Jacobians <a class="header-anchor" href="#Matrix-Operator-RT-and-Jacobians" aria-label="Permalink to &quot;Matrix-Operator RT and Jacobians {#Matrix-Operator-RT-and-Jacobians}&quot;">​</a></h2><ul><li><p>Sanghavi, S. V., Martonchik, J. V., Davis, A. B., and Diner, D. J. (2013). Linearization of a scalar matrix operator method radiative transfer model with respect to aerosol and surface properties. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 116, 1-16. <a href="https://doi.org/10.1016/j.jqsrt.2012.10.021" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2012.10.021</a></p></li><li><p>Sanghavi, S., Davis, A. B., and Eldering, A. (2014). vSmartMOM: A vector matrix operator method-based radiative transfer model linearized with respect to aerosol properties. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 133, 412-433. <a href="https://doi.org/10.1016/j.jqsrt.2013.09.004" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2013.09.004</a></p></li><li><p>Sanghavi, S. and Stephens, G. (2015). Adaptation of the delta-m and delta-fit truncation methods to vector radiative transfer: Effect of truncation on radiative transfer accuracy. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 159, 53-68. <a href="https://doi.org/10.1016/j.jqsrt.2015.03.007" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2015.03.007</a></p></li></ul><h2 id="Mie-Phase-Matrix-Fourier-Decomposition" tabindex="-1">Mie Phase-Matrix Fourier Decomposition <a class="header-anchor" href="#Mie-Phase-Matrix-Fourier-Decomposition" aria-label="Permalink to &quot;Mie Phase-Matrix Fourier Decomposition {#Mie-Phase-Matrix-Fourier-Decomposition}&quot;">​</a></h2><ul><li>Sanghavi, S. (2014). Revisiting the Fourier expansion of Mie scattering matrices in generalized spherical functions. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 136, 16-27. <a href="https://doi.org/10.1016/j.jqsrt.2013.12.015" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2013.12.015</a> (NAI-2 vs PCW comparison; corrected Domke formalism.)</li></ul><h2 id="Raman-Scattering" tabindex="-1">Raman Scattering <a class="header-anchor" href="#Raman-Scattering" aria-label="Permalink to &quot;Raman Scattering {#Raman-Scattering}&quot;">​</a></h2><ul><li><p>Sanghavi, S. (2022). Raman scattering in the Earth&#39;s atmosphere, Part I: Optical properties. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 291, 108328. <a href="https://doi.org/10.1016/j.jqsrt.2022.108328" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2022.108328</a></p></li><li><p>Sanghavi, S. and Frankenberg, C. (2023). Raman scattering in the Earth&#39;s atmosphere, Part II: Radiative transfer modeling for remote sensing applications. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 311, 108791. <a href="https://doi.org/10.1016/j.jqsrt.2023.108791" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2023.108791</a></p></li><li><p>Sanghavi, S. (2026). Isolating Cabannes and rotational Raman scattering to determine forward modeling error due to Rayleigh scattering in the Earth&#39;s atmosphere. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 363, 110077. <a href="https://doi.org/10.1016/j.jqsrt.2026.110077" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2026.110077</a></p></li></ul><h2 id="Exoplanets-and-Brown-Dwarfs" tabindex="-1">Exoplanets and Brown Dwarfs <a class="header-anchor" href="#Exoplanets-and-Brown-Dwarfs" aria-label="Permalink to &quot;Exoplanets and Brown Dwarfs {#Exoplanets-and-Brown-Dwarfs}&quot;">​</a></h2><ul><li><p>Sanghavi, S. and Shporer, A. (2018). Photopolarimetric characteristics of brown dwarfs. I. Uniform cloud decks. <em>The Astrophysical Journal</em>, 866, 28. <a href="https://doi.org/10.3847/1538-4357/aadf94" target="_blank" rel="noreferrer">https://doi.org/10.3847/1538-4357/aadf94</a></p></li><li><p>Sanghavi, S. and West, R. (2019). Spectropolarimetric characteristics of brown dwarfs. II. Uniform clouds. <em>The Astrophysical Journal</em>, 877, 134. <a href="https://doi.org/10.3847/1538-4357/ab1b4e" target="_blank" rel="noreferrer">https://doi.org/10.3847/1538-4357/ab1b4e</a></p></li><li><p>Sanghavi, S., West, R., and Jiang, J. (2021). Cloudy atmospheres on directly imaged exoplanets: The need for accurate particulate representation in photopolarimetric simulations. <em>The Astrophysical Journal</em>, 907, 30. <a href="https://doi.org/10.3847/1538-4357/abcd99" target="_blank" rel="noreferrer">https://doi.org/10.3847/1538-4357/abcd99</a></p></li></ul><h2 id="Spectroscopic-Data-HITRAN-and-related" tabindex="-1">Spectroscopic Data (HITRAN and related) <a class="header-anchor" href="#Spectroscopic-Data-HITRAN-and-related" aria-label="Permalink to &quot;Spectroscopic Data (HITRAN and related) {#Spectroscopic-Data-HITRAN-and-related}&quot;">​</a></h2><p>vSmartMOM computes gas absorption from <a href="https://hitran.org" target="_blank" rel="noreferrer">HITRAN</a> line parameters, through <a href="https://github.com/RemoteSensingTools/AtmosphericAbsorption.jl" target="_blank" rel="noreferrer">AtmosphericAbsorption.jl</a>. The spectroscopic parameters behind every line-by-line cross-section come from HITRAN, so <strong>if you publish results computed with HITRAN data, please cite the HITRAN edition you used</strong>, together with any of the data sources below that your calculation used. BibTeX entries are in <code>CITATION.bib</code>.</p><h3 id="Which-HITRAN-edition-did-I-use?" tabindex="-1">Which HITRAN edition did I use? <a class="header-anchor" href="#Which-HITRAN-edition-did-I-use?" aria-label="Permalink to &quot;Which HITRAN edition did I use? {#Which-HITRAN-edition-did-I-use?}&quot;">​</a></h3><ul><li><p><strong>Default (<code>&quot;artifact&quot;</code> edition):</strong> HITRAN2016, distributed as Julia artifacts. This is what <code>artifact(&quot;CO2&quot;)</code> and YAML configurations use unless you change the edition.</p></li><li><p><strong>Downloaded data (<code>set_hitran_edition!</code>, <code>fetch_hitran</code>):</strong> hitran.org serves only the <em>current</em> edition — HITRAN2024 at the time of writing. The edition string is a cache and provenance label; it does not select an older edition from the server. <code>hitran_info(molecule)</code> reports the download date and checksum recorded with the data.</p></li><li><p><strong>Your own <code>.par</code> files:</strong> cite the edition the file came from.</p></li></ul><h3 id="HITRAN" tabindex="-1">HITRAN <a class="header-anchor" href="#HITRAN" aria-label="Permalink to &quot;HITRAN {#HITRAN}&quot;">​</a></h3><ul><li><p>Gordon, I. E., Rothman, L. S., Hargreaves, R. J., et al. (2026). The HITRAN2024 molecular spectroscopic database. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 353, 109807. <a href="https://doi.org/10.1016/j.jqsrt.2026.109807" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2026.109807</a></p></li><li><p>Gordon, I. E., Rothman, L. S., Hargreaves, R. J., et al. (2022). The HITRAN2020 molecular spectroscopic database. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 277, 107949. <a href="https://doi.org/10.1016/j.jqsrt.2021.107949" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2021.107949</a></p></li><li><p>Gordon, I. E., Rothman, L. S., Hill, C., et al. (2017). The HITRAN2016 molecular spectroscopic database. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 203, 3-69. <a href="https://doi.org/10.1016/j.jqsrt.2017.06.038" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2017.06.038</a></p></li></ul><h3 id="Partition-sums" tabindex="-1">Partition sums <a class="header-anchor" href="#Partition-sums" aria-label="Permalink to &quot;Partition sums {#Partition-sums}&quot;">​</a></h3><ul><li><p>Gamache, R. R., Vispoel, B., Rey, M., et al. (2021). Total internal partition sums for the HITRAN2020 database. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 271, 107713. <a href="https://doi.org/10.1016/j.jqsrt.2021.107713" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2021.107713</a> (TIPS-2021, used by AtmosphericAbsorption.jl and hence by the RT pipeline.)</p></li><li><p>Gamache, R. R., Roller, C., Lopes, E., et al. (2017). Total internal partition sums for 166 isotopologues of 51 molecules important in planetary atmospheres: Application to HITRAN2016 and beyond. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 203, 70-87. <a href="https://doi.org/10.1016/j.jqsrt.2017.03.045" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2017.03.045</a> (TIPS-2017, used by the deprecated internal <code>vSmartMOM.Absorption</code> line engine.)</p></li></ul><h3 id="HAPI,-collision-induced-absorption-and-the-water-vapour-continuum" tabindex="-1">HAPI, collision-induced absorption and the water-vapour continuum <a class="header-anchor" href="#HAPI,-collision-induced-absorption-and-the-water-vapour-continuum" aria-label="Permalink to &quot;HAPI, collision-induced absorption and the water-vapour continuum {#HAPI,-collision-induced-absorption-and-the-water-vapour-continuum}&quot;">​</a></h3><ul><li><p>Kochanov, R. V., Gordon, I. E., Rothman, L. S., et al. (2016). HITRAN Application Programming Interface (HAPI): A comprehensive approach to working with spectroscopic data. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 177, 15-30. <a href="https://doi.org/10.1016/j.jqsrt.2016.03.005" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2016.03.005</a> (Cite when using non-Voigt line profiles or parameters through AtmosphericAbsorption.jl.)</p></li><li><p>Karman, T., Gordon, I. E., van der Avoird, A., et al. (2019). Update of the HITRAN collision-induced absorption section. <em>Icarus</em>, 328, 160-175. <a href="https://doi.org/10.1016/j.icarus.2019.02.034" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.icarus.2019.02.034</a> (Cite when using HITRAN <code>.cia</code> files.)</p></li><li><p>Mlawer, E. J., Payne, V. H., Moncet, J.-L., et al. (2012). Development and recent evaluation of the MT_CKD model of continuum absorption. <em>Philosophical Transactions of the Royal Society A</em>, 370, 2520-2556. <a href="https://doi.org/10.1098/rsta.2011.0295" target="_blank" rel="noreferrer">https://doi.org/10.1098/rsta.2011.0295</a></p></li><li><p>Mlawer, E. J., Cady-Pereira, K. E., Mascio, J., and Gordon, I. E. (2023). The inclusion of the MT_CKD water vapor continuum model in the HITRAN molecular spectroscopic database. <em>Journal of Quantitative Spectroscopy and Radiative Transfer</em>, 306, 108645. <a href="https://doi.org/10.1016/j.jqsrt.2023.108645" target="_blank" rel="noreferrer">https://doi.org/10.1016/j.jqsrt.2023.108645</a> (Cite both when using the MT_CKD water-vapour continuum.)</p></li></ul><p>ExoMol line lists used through AtmosphericAbsorption.jl have their own citation requirements; see that package&#39;s <a href="https://github.com/RemoteSensingTools/AtmosphericAbsorption.jl/blob/main/docs/src/citing.md" target="_blank" rel="noreferrer">citing page</a>.</p><h2 id="Background-References" tabindex="-1">Background References <a class="header-anchor" href="#Background-References" aria-label="Permalink to &quot;Background References {#Background-References}&quot;">​</a></h2><ul><li><p>Fell, F. (1997). <em>Validierung eines Modells zur Simulation des Strahlungstransportes in Atmosphäre und Ozean</em>.</p></li><li><p>Grant, I. P. and Hunt, G. E. (1969). Discrete space theory of radiative transfer I. Fundamentals. <em>Proceedings of the Royal Society of London A</em>, 313(1513), 183-197.</p></li><li><p>Plass, G. N., Kattawar, G. W., and Catchings, F. E. (1973). Matrix operator theory of radiative transfer. 1: Rayleigh scattering. <em>Applied Optics</em>, 12(2), 314-329.</p></li></ul>',27)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
